    {
        "source": 'cotco_giaitamgiac.tex',
        "caudan": '%[T10_C4_TV_01_VD]\n\t\tMột người quan sát đỉnh $D$ của cột cờ $CD$ từ hai vị trí $A$ và $B$ cách nhau một khoảng $45$m (thẳng hàng với $C$). \tBiết rằng từ  góc tạo bởi mặt đất và $AD$ bằng $44^{\\circ}$, góc tạo mặt đất  và $BD$ bằng $63^{\\circ}$.\\begin{center}\n\t\t\t\\begin{tikzpicture}\n\t\t\t\t% Đế tháp\n\t\t\t\t\\fill[gray!90] (5,0) rectangle (7,0.5); \n\t\t\t\t\\fill[gray!90] (5.2,0.5) rectangle (6.8,0.7); \n\t\t\t\t\\fill[gray!90] (5.4,0.7) rectangle (6.6,0.8); \n\t\t\t\t% Trụ tháp\n\t\t\t\t\\fill[gray!80] (5.5,0.8) -- (5.9,5)-- (6.1,5) -- (6.5,0.8) -- cycle;\n\t\t\t\t\\draw[thick, black] (6,5) -- (6,5.5); % Cột cờ\n\t\t\t\t\\draw[thick, black] (5.83,5.45) node[right]{\\twemoji[height=0.7em]{flag: Vietnam}};\n\t\t\t\t\\draw[thick] (-5,0) circle(1pt) node[below]{A} -- (5,0); \n\t\t\t\t\\draw[] (-3,0) circle(1pt)node[below]{B} --(6,5.5);\n\t\t\t\t\\draw[] (-5,0)--(6,5.5) node[above]{D};\n\t\t\t\t\\draw[] (6,0) circle(1pt)node[below]{C};\n\t\t\t\\end{tikzpicture}\t\n\t\t\\end{center}\\begin{enumerate} \n\t\t\t\n\t\t\t\\item Tính $\\widehat{ABD}$; \n\t\t\t\n\t\t\t\\item Tính $\\widehat{ADB}$; \n\t\t\t\n\t\t\t\\item Tính $BD$;\n\t\t\t\n\t\t\t\\item Tính $AD$;\n\t\t\t\n\t\t\t\\item Tính\t$CD$. \n\t\t\t\n\t\t\\end{enumerate}',
        "dapan": '38,8',
        "loigiai": '\\begin{enumerate} \n\t\t\t\t\\item $\\widehat{ABD} = 180^{\\circ} - 63^{\\circ} = 117^{\\circ}$.\n\t\t\t\t\\item $\\widehat{ADB} = 180^{\\circ} - 44^{\\circ} - 117^{\\circ} = 19^{\\circ}$.\n\t\t\t\t\\item Cạnh $BD=\\dfrac{\\sin A \\cdot AB }{\\sin D}=96.01561529497965$.\n\t\t\t\t\\item Cạnh $AD=\\dfrac{\\sin B \\cdot AB }{\\sin D}=123.15483882424046$.\n\t\t\t\t\\item Chiều cao tháp $h=CD=AD \\cdot \\sin A=85.55053965178733$.(làm tròn: $85.6$m).\n\t\t\t\\end{enumerate}',
    },
