def K10_TLN_ThucTe_OnTapChuong_Random():
    """Lấy ngẫu nhiên 1 câu từ Nửa 2 dành cho Ôn tập cuối chương IV"""
    q = random.choice(BANK_PART2)
    return q["caudan"], q["dapan"], q["loigiai"]

def K10_TLN_ThucTe_OnTapChuong_Dang1():
    """Dạng 1 Ôn tập chương: Khoảng cách và góc ngắm thực địa"""
    subset = [q for q in BANK_PART2 if any(w in q["caudan"].lower() for w in ["khoảng cách", "góc", "bờ biển", "đo", "đầm lầy"])]
    q = random.choice(subset) if subset else random.choice(BANK_PART2)
