def K10_C4_TLN_ChieuCao_TamGiac():
    caudan = r"""Cho $\Delta ABC$ có $AB = 8, AC = 5, \widehat{BAC} = 60^\circ$. Tính chiều cao $AH$ của $\Delta ABC$ (kết quả làm tròn đến hàng phần trăm)."""
    dapan = "4,95"
    loigiai = r"""Diện tích tam giác $ABC$ là:
$$S = \dfrac{1}{2} AB \cdot AC \sin A = \dfrac{1}{2} \cdot 8 \cdot 5 \cdot \sin 60^\circ = 10\sqrt{3}.$$
Độ dài cạnh $BC$:
$$BC^2 = AB^2 + AC^2 - 2 AB \cdot AC \cos A = 8^2 + 5^2 - 2 \cdot 8 \cdot 5 \cos 60^\circ = 64 + 25 - 40 = 49 \implies BC = 7.$$
Chiều cao $AH$ là:
$$AH = \dfrac{2S}{BC} = \dfrac{20\sqrt{3}}{7} \approx 4{,}95."""
    return caudan, dapan, loigiai

def K10_C4_TLN_BanKinhNoiTiep():
    caudan = r"""Cho tam giác $ABC$ có $\widehat{B} = 60^\circ, \widehat{A} = 30^\circ$, cạnh $BC = 12$. Tính bán kính đường tròn nội tiếp tam giác $ABC$ (kết quả làm tròn đến hàng phần trăm)."""
    dapan = "4,39"
    loigiai = r"""Ta có $\widehat{C} = 180^\circ - (30^\circ + 60^\circ) = 90^\circ$, do đó tam giác $ABC$ vuông tại $C$.
- Cạnh huyền $AB = \dfrac{BC}{\sin A} = \dfrac{12}{\sin 30^\circ} = 24$.
- Cạnh góc vuông $AC = \sqrt{AB^2 - BC^2} = \sqrt{24^2 - 12^2} = 12\sqrt{3}$.
Bán kính đường tròn nội tiếp tam giác vuông:
$$r = \dfrac{BC + AC - AB}{2} = \dfrac{12 + 12\sqrt{3} - 24}{2} = 6\sqrt{3} - 6 \approx 4{,}39."""
    return caudan, dapan, loigiai

def K10_C4_TLN_CucTri_DienTich():
    caudan = r"""Cho $\Delta ABC$ có $BC = a, AC = b$. Tam giác $ABC$ có diện tích lớn nhất khi góc $\widehat{C}$ bằng bao nhiêu độ?"""
    dapan = "90"
    loigiai = r"""Diện tích tam giác $ABC$ được tính bởi công thức:
$$S = \dfrac{1}{2} ab \sin C.$$
Vì $0 < \sin C \le 1$ nên $S \le \dfrac{1}{2} ab$.
Dấu bằng xảy ra khi $\sin C = 1 \iff \widehat{C} = 90^\circ$.
Vậy diện tích tam giác đạt lớn nhất khi $\widehat{C} = 90^\circ$."""
    return caudan, dapan, loigiai

def K10_C4_TLN_ThucTe_ChieuCaoNgonNui():
    caudan = r"""\immini{Từ hai vị trí $A, B$ của một tòa nhà người ta quan sát đỉnh $C$ của ngọn núi. Biết rằng độ cao $AB$ bằng $70\text{ m}$, phương nhìn $AC$ tạo với phương nằm ngang một góc $30^\circ$, phương nhìn $BC$ tạo với phương nằm ngang một góc $15^\circ 30'$. Ngọn núi đó có độ cao so với mặt đất xấp xỉ bằng bao nhiêu mét (làm tròn đến hàng đơn vị)?}{
\begin{tikzpicture}[scale=0.5, line join=round, line cap=round]
    \coordinate (A) at (0,0);
    \coordinate (B) at (0,1.8);
    \coordinate (H) at (5.5,0);
    \coordinate (D) at (5.5,1.8);
    \coordinate (C) at (5.5,4.5);
    \draw[thick] (A) -- (H) -- (C) -- cycle;
    \draw[thick] (A) -- (B) node[midway, left] {$70$};
    \draw[thick] (B) -- (C);
    \draw[thick] (B) -- (D);
    \node[below left] at (A) {$A$};
    \node[left] at (B) {$B$};
    \node[above] at (C) {$C$};
    \node[right] at (D) {$D$};
    \node[below right] at (H) {$H$};
    \draw (0.8,0) arc (0:30:0.8) node[right, pos=0.5, scale=0.7] {$30^\circ$};
    \draw (0.8,1.8) arc (0:15.5:0.8) node[right, pos=0.5, scale=0.6] {$15^\circ 30'$};
    \draw (5.2,0) |- (5.5,0.3);
\end{tikzpicture}
}"""
    dapan = "135"
    loigiai = r"""Đặt $CD = h$. Khi đó chiều cao ngọn núi so với mặt đất là $CH = h + 70$.
Trong tam giác vuông $BCD$: $BD = \dfrac{CD}{\tan 15^\circ 30'} = \dfrac{h}{\tan 15^\circ 30'}$.
Trong tam giác vuông $ACH$: $AH = \dfrac{CH}{\tan 30^\circ} = \dfrac{h + 70}{\tan 30^\circ}$.
Vì $BD = AH$ nên ta có phương trình:
$$\dfrac{h}{\tan 15^\circ 30'} = \dfrac{h + 70}{\tan 30^\circ} \iff h \tan 30^\circ = (h + 70) \tan 15^\circ 30'$$
$$\iff h = \dfrac{70 \cdot \tan 15^\circ 30'}{\tan 30^\circ - \tan 15^\circ 30'} \approx \dfrac{70 \cdot 0{,}2773}{0{,}5774 - 0{,}2773} \approx 64{,}7\text{ m}.$$
Vậy chiều cao ngọn núi so với mặt đất là:
$$CH = h + 70 \approx 64{,}7 + 70 \approx 135\text{ m}.$$"""
    return caudan, dapan, loigiai

